using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        builder.Entity<Shipment>(entity =>
        {
            entity.HasIndex(s => s.TrackingNumber).IsUnique();
        });

        // Seed sample data
        builder.Entity<Shipment>().HasData(
            new Shipment { Id = 1, TrackingNumber = "TRK-001-2026", Origin = "New York, US", Destination = "London, UK", Status = ShipmentStatus.InTransit, ShippedDate = new DateTime(2026, 7, 1), EstimatedDelivery = new DateTime(2026, 7, 12), CustomerEmail = "customer1@example.com", Description = "Electronics - 2 pallets" },
            new Shipment { Id = 2, TrackingNumber = "TRK-002-2026", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = ShipmentStatus.OutForDelivery, ShippedDate = new DateTime(2026, 6, 25), EstimatedDelivery = new DateTime(2026, 7, 9), CustomerEmail = "customer2@example.com", Description = "Auto parts - 1 container" },
            new Shipment { Id = 3, TrackingNumber = "TRK-003-2026", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = ShipmentStatus.Pending, ShippedDate = new DateTime(2026, 7, 7), EstimatedDelivery = new DateTime(2026, 7, 20), CustomerEmail = "customer3@example.com", Description = "Machinery components" },
            new Shipment { Id = 4, TrackingNumber = "TRK-004-2026", Origin = "São Paulo, BR", Destination = "Sydney, AU", Status = ShipmentStatus.Delayed, ShippedDate = new DateTime(2026, 6, 20), EstimatedDelivery = new DateTime(2026, 7, 15), CustomerEmail = "customer1@example.com", Description = "Agricultural equipment" },
            new Shipment { Id = 5, TrackingNumber = "TRK-005-2026", Origin = "Mumbai, IN", Destination = "Dubai, AE", Status = ShipmentStatus.Delivered, ShippedDate = new DateTime(2026, 6, 28), EstimatedDelivery = new DateTime(2026, 7, 5), CustomerEmail = "customer2@example.com", Description = "Textiles - 5 boxes" }
        );
    }
}

